llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "KNI-272, a structurally closely related peptidomimetic protease inhibitor with the same tert-butylamide and hydroxyethylene core, showed absolute oral bioavailability of 54.97 ± 19.78% in fasting patients, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Atazanavir, a large peptidomimetic HIV protease inhibitor with multiple amides and a tert-butyl group, has an absolute oral bioavailability of 68% (57–80%) in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Darunavir, another peptidomimetic protease inhibitor with multiple hydrogen-bonding groups and moderate lipophilicity, has 37% oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In children, KNI-272 absolute bioavailability was only 12% (range 3.5–25%), showing that the same scaffold can fall below 20% in certain populations or formulations, which tempers confidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alvimopan, a piperidine-containing aryl amide with a phenol, has very low absolute oral bioavailability (6%) in humans, but its zwitterionic carboxylic acid and lower transferability limit direct applicability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a peptidomimetic protease-inhibitor-like molecule closely related to KNI-272 (transfer score 0.969), whose adult absolute oral bioavailability is consistently 29–55%, and to other HIV protease inhibitors with F 37–68%. Although pediatric KNI-272 data and alvimopan show low F, the high-transfer adult data dominate and support F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Pediatric and formulation-dependent variability in the closest analogue leaves uncertainty.",
    "Food effects, dose effects, and metabolic/efflux liabilities are not fully characterized for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

